using System;using System.IO;using System.Text.Json;
class MacInstallTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static int Main(string[] args){string root=Path.GetFullPath(args[0]),engine=Path.Combine(root,"source/engine"),extension=Path.Combine(root,"source/extension"),target=Path.Combine(root,"安装 有空格"),browsers=Path.Combine(root,"browser profiles");Directory.CreateDirectory(engine);Directory.CreateDirectory(extension);File.WriteAllText(Path.Combine(engine,"QingcunHost"),"new host");File.WriteAllText(Path.Combine(extension,"manifest.json"),"new UI");MacInstallCore.Install(engine,extension,target,browsers,true,()=>{});Check(File.Exists(Path.Combine(target,"native/QingcunHost")),"Mac install files copied");var d=JsonDocument.Parse(File.ReadAllText(Path.Combine(browsers,"Google/Chrome/NativeMessagingHosts/com.qingcun.video_downloader.json")));Check(d.RootElement.GetProperty("path").GetString()==Path.Combine(target,"native/QingcunHost"),"native messaging uses actual path with spaces");Directory.CreateDirectory(Path.Combine(target,"native/data"));string setting=Path.Combine(target,"native/data/settings.json");File.WriteAllText(setting,"{\"analysisEnabled\":false,\"folder\":\"原资料\"}");string before=File.ReadAllText(setting);File.WriteAllText(Path.Combine(target,"native/QingcunHost"),"old host");bool failed=false;try{MacInstallCore.Install(engine,extension,target,browsers,true,()=>{throw new Exception("validation failure");});}catch{failed=true;}Check(failed&&File.ReadAllText(Path.Combine(target,"native/QingcunHost"))=="old host","failed installation restores previous program");Check(File.ReadAllText(setting)==before,"failure retains personal data");MacInstallCore.Install(engine,extension,target,browsers,true,()=>{});Check(File.ReadAllText(setting)==before,"upgrade preserves off state and other settings");var only=Path.Combine(root,"eagle only");MacInstallCore.Install(engine,extension,only,Path.Combine(root,"unused browsers"),false,()=>{});Check(!Directory.Exists(Path.Combine(only,"extension"))&&!Directory.Exists(Path.Combine(root,"unused browsers")),"Eagle-only skips browser registration");bool blocked=false;try{MacInstallCore.SafePath(root,"../escape");}catch{blocked=true;}Check(blocked,"archive-relative paths cannot escape root");Console.WriteLine("MAC INSTALL CORE TESTS PASSED (Windows cross-platform execution)");return 0;}
}
